mapper.update:
UPDATE point_account
SET balance = balance - #{amount},
    total_used = total_used + #{amount},
    updated_at = NOW()
WHERE id = #{accountId}
  AND balance >= #{amount}

mapper.select:
SELECT id, user_id, balance, total_earned, total_used, created_at, updated_at, version FROM point_account
user_id = #{userId}
ORDER BY updated_at DESC
